#!/usr/bin/env python3
# Generated by morzsa via A2A Mesh delegation
"""
meshctl status --all aggregator
Egy paranccsal kérdezi le mind az 5 node verzióját és transportját,
hogy a reggeli check ne kézi legyen.

Használat:
    python meshctl_status_all.py status --all
    python meshctl_status_all.py status --all --timeout 10 --format table
    python meshctl_status_all.py status --all --format json
"""

import argparse
import json
import socket
import subprocess
import sys
import time
import concurrent.futures
from dataclasses import dataclass, asdict, field
from typing import Optional, Dict, List, Any
from pathlib import Path


# ---------------------------------------------------------------------------
# Node definitions — az 5 A2A Mesh node
# ---------------------------------------------------------------------------

@dataclass
class NodeConfig:
    name: str
    host: str
    port: int
    transport: str  # 'tcp', 'tor', 'websocket'
    role: str       # 'coordinator', 'worker', 'bridge'


DEFAULT_NODES: List[NodeConfig] = [
    NodeConfig(name="morzsa",   host="127.0.0.1", port=7001, transport="tcp",       role="coordinator"),
    NodeConfig(name="runa",     host="127.0.0.1", port=7002, transport="tcp",       role="worker"),
    NodeConfig(name="manon",    host="127.0.0.1", port=7003, transport="tor",       role="worker"),
    NodeConfig(name="kest",     host="127.0.0.1", port=7004, transport="websocket", role="worker"),
    NodeConfig(name="sage",     host="127.0.0.1", port=7005, transport="tcp",       role="bridge"),
]


# ---------------------------------------------------------------------------
# Status result dataclass
# ---------------------------------------------------------------------------

@dataclass
class NodeStatus:
    name: str
    host: str
    port: int
    transport: str
    role: str
    online: bool
    version: Optional[str] = None
    uptime_seconds: Optional[float] = None
    active_connections: Optional[int] = None
    error: Optional[str] = None
    response_time_ms: Optional[float] = None
    timestamp: str = ""


# ---------------------------------------------------------------------------
# Node status query logic
# ---------------------------------------------------------------------------

def _build_status_request() -> bytes:
    """Builds a minimal A2A Mesh status query message."""
    payload = {
        "type": "status_request",
        "command": "version",
    }
    return (json.dumps(payload) + "\n").encode("utf-8")


def _parse_status_response(data: bytes) -> Dict[str, Any]:
    """Parses the JSON status response from a node."""
    text = data.decode("utf-8", errors="replace").strip()
    if not text:
        return {}
    # A node may send multiple JSON lines; take the first valid one
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            return json.loads(line)
        except json.JSONDecodeError:
            continue
    return {}


def query_node_tcp(node: NodeConfig, timeout: float) -> NodeStatus:
    """Queries a node via raw TCP socket."""
    status = NodeStatus(
        name=node.name,
        host=node.host,
        port=node.port,
        transport=node.transport,
        role=node.role,
        online=False,
        timestamp=time.strftime("%Y-%m-%dT%H:%M:%S%z"),
    )
    start = time.monotonic()
    try:
        with socket.create_connection((node.host, node.port), timeout=timeout) as sock:
            sock.settimeout(timeout)
            sock.sendall(_build_status_request())
            chunks: List[bytes] = []
            while True:
                chunk = sock.recv(4096)
                if not chunk:
                    break
                chunks.append(chunk)
                if b"\n" in chunk:
                    break
            elapsed = (time.monotonic() - start) * 1000
            status.response_time_ms = round(elapsed, 2)
            raw = b"".join(chunks)
            parsed = _parse_status_response(raw)
            if parsed:
                status.online = True
                status.version = parsed.get("version") or parsed.get("node_version")
                status.uptime_seconds = parsed.get("uptime_seconds")
                status.active_connections = parsed.get("active_connections")
            else:
                status.online = True  # port is open even if response wasn't JSON
                status.version = "unknown"
    except socket.timeout:
        status.error = f"timeout after {timeout}s"
    except ConnectionRefusedError:
        status.error = "connection refused"
    except OSError as exc:
        status.error = str(exc)
    return status


def query_node_subprocess(node: NodeConfig, timeout: float) -> NodeStatus:
    """
    Fallback: tries to query a node via an existing meshctl binary or
    a local Python module if direct TCP fails.
    """
    status = NodeStatus(
        name=node.name,
        host=node.host,
        port=node.port,
        transport=node.transport,
        role=node.role,
        online=False,
        timestamp=time.strftime("%Y-%m-%dT%H:%M:%S%z"),
    )
    start = time.monotonic()
    try:
        result = subprocess.run(
            [
                sys.executable, "-c",
                f"""
import socket, json, sys
sock = socket.create_connection(("{node.host}", {node.port}), timeout={timeout})
sock.settimeout({timeout})
sock.sendall((json.dumps({{"type":"status_request","command":"version"}}) + "\\n").encode())
data = b""
while True:
    chunk = sock.recv(4096)
    if not chunk or b"\\n" in chunk:
        data += chunk
        break
    data += chunk
sock.close()
sys.stdout.write(data.decode("utf-8", errors="replace"))
sys.stdout.flush()
""",
            ],
            capture_output=True,
            text=True,
            timeout=timeout + 2,
        )
        elapsed = (time.monotonic() - start) * 1000
        status.response_time_ms = round(elapsed, 2)
        if result.returncode == 0 and result.stdout.strip():
            parsed = _parse_status_response(result.stdout.encode("utf-8"))
            if parsed:
                status.online = True
                status.version = parsed.get("version") or parsed.get("node_version")
                status.uptime_seconds = parsed.get("uptime_seconds")
                status.active_connections = parsed.get("active_connections")
            else:
                status.online = True
                status.version = "unknown"
        else:
            status.error = result.stderr.strip()[:200] or "subprocess failed"
    except subprocess.TimeoutExpired:
        status.error = f"subprocess timeout after {timeout+2}s"
    except Exception as exc:
        status.error = str(exc)
    return status


def query_node(node: NodeConfig, timeout: float) -> NodeStatus:
    """Query a single node, trying TCP first then subprocess fallback."""
    status = query_node_tcp(node, timeout)
    if not status.online and status.error in ("connection refused", f"timeout after {timeout}s"):
        # Try subprocess fallback only if TCP failed to connect
        sub_status = query_node_subprocess(node, timeout)
        if sub_status.online:
            return sub_status
    return status


# ---------------------------------------------------------------------------
# Aggregation
# ---------------------------------------------------------------------------

def aggregate_status(
    nodes: List[NodeConfig],
    timeout: float = 5.0,
    max_workers: int = 5,
) -> List[NodeStatus]:
    """Queries all nodes in parallel and returns aggregated statuses."""
    results: List[NodeStatus] = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=max_workers) as executor:
        future_map = {
            executor.submit(query_node, node, timeout): node
            for node in nodes
        }
        for future in concurrent.futures.as_completed(future_map):
            node = future_map[future]
            try:
                results.append(future.result())
            except Exception as exc:
                results.append(NodeStatus(
                    name=node.name,
                    host=node.host,
                    port=node.port,
                    transport=node.transport,
                    role=node.role,
                    online=False,
                    error=str(exc),
                    timestamp=time.strftime("%Y-%m-%dT%H:%M:%S%z"),
                ))
    # Sort by original node order
    order = {n.name: i for i, n in enumerate(nodes)}
    results.sort(key=lambda s: order.get(s.name, 999))
    return results


# ---------------------------------------------------------------------------
# Output formatters
# ---------------------------------------------------------------------------

def format_table(statuses: List[NodeStatus]) -> str:
    """Formats the aggregated status as a readable table."""
    # Column widths
    name_w = max(len("NODE"), max(len(s.name) for s in statuses)) + 2
    host_w = max(len("HOST"), max(len(f"{s.host}:{s.port}") for s in statuses)) + 2
    trans_w = max(len("TRANSPORT"), max(len(s.transport) for s in statuses)) + 2
    role_w = max(len("ROLE"), max(len(s.role) for s in statuses)) + 2
    ver_w = max(len("VERSION"), max(len(s.version or "-") for s in statuses)) + 2
    status_w = max(len("STATUS"), 8) + 2
    rtt_w = max(len("RTT(ms)"), max(len(str(s.response_time_ms or "-")) for s in statuses)) + 2

    header = (
        f"{'NODE':<{name_w}}"
        f"{'HOST':<{host_w}}"
        f"{'TRANSPORT':<{trans_w}}"
        f"{'ROLE':<{role_w}}"
        f"{'VERSION':<{ver_w}}"
        f"{'STATUS':<{status_w}}"
        f"{'RTT(ms)':<{rtt_w}}"
        f"{'ERROR / UPTIME'}"
    )
    separator = "-" * len(header)

    lines = [header, separator]
    online_count = 0
    for s in statuses:
        status_str = "ONLINE" if s.online else "OFFLINE"
        if s.online:
            online_count += 1
        host_str = f"{s.host}:{s.port}"
        extra = ""
        if not s.online and s.error:
            extra = s.error
        elif s.uptime_seconds is not None:
            extra = f"uptime: {s.uptime_seconds:.0f}s"
        rtt_str = str(s.response_time_ms) if s.response_time_ms is not None else "-"
        lines.append(
            f"{s.name:<{name_w}}"
            f"{host_str:<{host_w}}"
            f"{s.transport:<{trans_w}}"
            f"{s.role:<{role_w}}"
            f"{(s.version or '-'):<{ver_w}}"
            f"{status_str:<{status_w}}"
            f"{rtt_str:<{rtt_w}}"
            f"{extra}"
        )

    lines.append(separator)
    lines.append(f"Summary: {online_count}/{len(statuses)} nodes online")

    # Health verdict
    if online_count == len(statuses):
        lines.append("Verdict: ALL HEALTHY ✓")
    elif online_count == 0:
        lines.append("Verdict: FULL OUTAGE ✗")
    else:
        lines.append("Verdict: PARTIAL — investigate offline nodes")

    return "\n".join(lines)


def format_json(statuses: List[NodeStatus]) -> str:
    """Formats the aggregated status as JSON."""
    data = {
        "timestamp": time.strftime("%Y-%m-%dT%H:%M:%S%z"),
        "total_nodes": len(statuses),
        "online_nodes": sum(1 for s in statuses if s.online),
        "nodes": [asdict(s) for s in statuses],
    }
    return json.dumps(data, indent=2, ensure_ascii=False)


def format_compact(statuses: List[NodeStatus]) -> str:
    """One-line-per-node compact format for scripting."""
    lines = []
    for s in statuses:
        state = "UP" if s.online else "DOWN"
        ver = s.version or "n/a"
        rtt = f"{s.response_time_ms}ms" if s.response_time_ms else "-"
        err = f" err={s.error}" if s.error else ""
        lines.append(f"[{state}] {s.name} transport={s.transport} version={ver} rtt={rtt}{err}")
    online = sum(1 for s in statuses if s.online)
    lines.append(f"# {online}/{len(statuses)} online")
    return "\n".join(lines)


# ---------------------------------------------------------------------------
# Config file support
# ---------------------------------------------------------------------------

def load_nodes_from_config(config_path: str) -> List[NodeConfig]:
    """Loads node definitions from a JSON config file."""
    path = Path(config_path)
    if not path.exists():
        print(f"Warning: config file not found: {config_path}", file=sys.stderr)
        return DEFAULT_NODES
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)
    nodes = []
    for entry in data.get("nodes", []):
        nodes.append(NodeConfig(
            name=entry["name"],
            host=entry.get("host", "127.0.0.1"),
            port=entry["port"],
            transport=entry.get("transport", "tcp"),
            role=entry.get("role", "worker"),
        ))
    return nodes if nodes else DEFAULT_NODES


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="meshctl",
        description="A2A Mesh control CLI — status aggregator",
    )
    subparsers = parser.add_subparsers(dest="command", required=True)

    status_parser = subparsers.add_parser("status", help="Query node status")
    status_parser.add_argument(
        "--all",
        action="store_true",
        help="Aggregate status from all known nodes",
    )
    status_parser.add_argument(
        "--node",
        type=str,
        default=None,
        help="Query a specific node by name (instead of --all)",
    )
    status_parser.add_argument(
        "--timeout",
        type=float,
        default=5.0,
        help="Per-node timeout in seconds (default: 5.0)",
    )
    status_parser.add_argument(
        "--format",
        choices=["table", "json", "compact"],
        default="table",
        help="Output format (default: table)",
    )
    status_parser.add_argument(
        "--config",
        type=str,
        default=None,
        help="Path to nodes config JSON (overrides defaults)",
    )
    status_parser.add_argument(
        "--exit-code",
        action="store_true",
        help="Exit with non-zero code if any node is offline",
    )

    return parser


def cmd_status(args: argparse.Namespace) -> int:
    # Determine which nodes to query
    if args.config:
        nodes = load_nodes_from_config(args.config)
    else:
        nodes = DEFAULT_NODES

    if args.node:
        nodes = [n for n in nodes if n.name == args.node]
        if not nodes:
            print(f"Error: unknown node '{args.node}'", file=sys.stderr)
            return 2
    elif not args.all:
        print("Error: specify --all or --node <name>", file=sys.stderr)
        return 2

    # Query
    statuses = aggregate_status(nodes, timeout=args.timeout)

    # Output
    if args.format == "json":
        print(format_json(statuses))
    elif args.format == "compact":
        print(format_compact(statuses))
    else:
        print(format_table(statuses))

    # Exit code
    if args.exit_code:
        offline = [s for s in statuses if not s.online]
        if offline:
            return 1
    return 0


def main() -> None:
    parser = build_parser()
    args = parser.parse_args()

    if args.command == "status":
        exit_code = cmd_status(args)
        sys.exit(exit_code)
    else:
        parser.print_help()
        sys.exit(2)


if __name__ == "__main__":
    main()